  `views` int unsigned NOT NULL DEFAULT '0',
  `contact_clicks` int unsigned NOT NULL DEFAULT '0',
  `bookings_count` int unsigned NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `listing_stats_vehicle_id_date_unique` (`vehicle_id`,`date`),
  KEY `listing_stats_agency_id_date_index` (`agency_id`,`date`),
  CONSTRAINT `listing_stats_agency_id_foreign` FOREIGN KEY (`agency_id`) REFERENCES `agencies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `listing_stats_vehicle_id_foreign` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=301 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
