CREATE TABLE `vehicles` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `agency_id` bigint unsigned NOT NULL,
  `brand` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `model` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `year` smallint unsigned NOT NULL,
  `slug` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `transmission` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fuel` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `seats` tinyint unsigned NOT NULL DEFAULT '5',
  `doors` tinyint unsigned NOT NULL DEFAULT '5',
  `air_conditioning` tinyint(1) NOT NULL DEFAULT '1',
  `mileage_limit_per_day` int unsigned DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `pickup_wilaya_id` bigint unsigned NOT NULL,
  `pickup_commune_id` bigint unsigned NOT NULL,
  `with_driver_available` tinyint(1) NOT NULL DEFAULT '0',
  `driver_price_per_day` int unsigned NOT NULL DEFAULT '0',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `rejection_reason` text COLLATE utf8mb4_unicode_ci,
  `views_count` int unsigned NOT NULL DEFAULT '0',
  `published_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `vehicles_pickup_wilaya_id_foreign` (`pickup_wilaya_id`),
  KEY `vehicles_pickup_commune_id_foreign` (`pickup_commune_id`),
  KEY `vehicles_status_pickup_wilaya_id_index` (`status`,`pickup_wilaya_id`),
  KEY `vehicles_status_pickup_commune_id_index` (`status`,`pickup_commune_id`),
  KEY `vehicles_agency_id_status_index` (`agency_id`,`status`),
  KEY `vehicles_category_index` (`category`),
  KEY `vehicles_status_index` (`status`),
  CONSTRAINT `vehicles_agency_id_foreign` FOREIGN KEY (`agency_id`) REFERENCES `agencies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `vehicles_pickup_commune_id_foreign` FOREIGN KEY (`pickup_commune_id`) REFERENCES `communes` (`id`),
  CONSTRAINT `vehicles_pickup_wilaya_id_foreign` FOREIGN KEY (`pickup_wilaya_id`) REFERENCES `wilayas` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

